 <th>Priority</th>
 <th>Status</th>
 <th>Expected Delivery</th>
 </tr>
 </thead>
 <tbody>
 {orders.map((o, i) => (
 <tr key={i}>
 <td><strong className="record-link">{dv(o.number)}</strong></td>
 <td className="truncate">{dv(o.supplier)}</td>
 <td className="text-right">{dv(o.total_cost)} {dv(o.currency)}</td>
 <td><span className={priorityClass(dv(o.priority))}>{dv(o.priority)}</span></td>
 <td><span className={statusClass(dv(o.status))}>{dv(o.status)}</span></td>
 <td>{formatDate(dv(o.expected_delivery_date))}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 )}
 </div>
 </div>
 );
}

// ── Summary Metrics ──────────────────────────────────────────────────
function SummaryMetrics() {
 const [metrics, setMetrics] = useState({
 openOrders: "—", prodActive: "—", lowStock: "—",
 qualityPending: "—", procOpen: "—",
 });
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 Promise.all([
 fetchCount("x_2056099_indust_0_cust_order", "statusNOT INcomplete,closed,cancelled,fulfilled,delivered"),
 fetchCount("x_2056099_indust_0_production_order", "status=in_progress^ORstatus=active^ORstatus=in_production^ORstatus=released"),
 fetchCount("x_2056099_indust_0_inv_stock", "available_quantity<reorder_level"),
 fetchCount("x_2056099_indust_0_qc_insp", "status=pending^ORstatus=in_progress"),
 fetchCount("x_2056099_indust_0_proc_order", "statusNOT INcomplete,closed,cancelled,received"),
 ]).then(([open, prod, low, quality, proc]) => {
 setMetrics({
 openOrders: open, prodActive: prod, lowStock: low,
 qualityPending: quality, procOpen: proc,
 });
 setLoading(false);
 }).catch(() => setLoading(false));
 }, []);

 if (loading) {
 return (
 <div className="summary-cards" id="overview">
 {[1, 2, 3, 4, 5].map(i => (
 <div className="summary-card skeleton" key={i}>
 <div className="skeleton-line short" />
 <div className="skeleton-line wide" />
 <div className="skeleton-line short" />
 </div>
 ))}
 </div>
 );
 }

 return (
 <div className="summary-cards" id="overview">
 <SummaryCard icon="📦" label="Open Orders" value={metrics.openOrders} variant="info" sub="Pending fulfillment" />
 <SummaryCard icon="🏭" label="Active Production" value={metrics.prodActive} variant="warning" sub="In progress" />
 <SummaryCard icon="🔴" label="Low Stock Alerts" value={metrics.lowStock} variant="critical" sub="Below reorder point" />
 <SummaryCard icon="🔍" label="Quality Pending" value={metrics.qualityPending} variant="neutral" sub="Inspections open" />
 <SummaryCard icon="🚚" label="Open POs" value={metrics.procOpen} variant="positive" sub="Awaiting delivery" />
 </div>
 );
}

// ── Main Dashboard App ───────────────────────────────────────────────
function App() {
 const [refreshKey, setRefreshKey] = useState(0);
 const [activeSection, setActiveSection] = useState("overview");
 const [lastRefresh, setLastRefresh] = useState(new Date());
 const mainRef = useRef<HTMLElement>(null);

 const handleRefresh = useCallback(() => {
 setRefreshKey(k => k + 1);
 setLastRefresh(new Date());
 }, []);

 const handleNavigate = useCallback((id: string) => {
 setActiveSection(id);
 const el = document.getElementById(id);
 if (el && mainRef.current) {
 el.scrollIntoView({ behavior: "smooth", block: "start" });
 }
 }, []);

 return (
 <div className="app-shell">
 <Sidebar activeSection={activeSection} onNavigate={handleNavigate} />
 <div className="main-wrapper">
 <Navbar onRefresh={handleRefresh} lastRefresh={lastRefresh} />
 <main className="main-content" ref={mainRef} key={refreshKey}>
 <SummaryMetrics />
 <AlertsSection />
 <CustomerOrdersSection />
 <div className="grid-2">
 <ProductionOrdersSection />
 <InventorySection />
 </div>
 <div className="grid-2">
 <QualitySection />
 <ProcurementSection />
 </div>
 <footer className="dashboard-footer">
 <span>Industrial Inventory &amp; Production Management</span>
 <span className="footer-dot">·</span>
 <span>Powered by ServiceNow</span>
 </footer>
 </main>
 </div>
 </div>
 );
}

// ── Bootstrap ────────────────────────────────────────────────────────
const root = document.getElementById("root");
if (root) {
 ReactDOM.createRoot(root).render(<App />);
}
